(345061, 27019, 327, '<td valign="top">Nice example of speed. Bit dark, colors are flat, but not too shabby.</td>', 'Nice example of speed. Bit dark, colors are flat, but not too shabby.', '2003-07-02 12:34:08.000000', NULL, 1),
(345062, 27144, 327, '<td valign="top">I like this. I like would of only cropped the top more. Nice job.</td>', 'I like this. I like would of only cropped the top more. Nice job.', '2003-07-02 12:34:43.000000', NULL, 1),
(345063, 27134, 3102, '<td valign="top">Meets the challenge, but I have to be honest in saying that it doesn''t strike me as being a compelling shot.</td>', 'Meets the challenge, but I have to be honest in saying that it doesn''t strike me as being a compelling shot.', '2003-07-02 12:35:23.000000', NULL, 1),
