INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(345163, 27192, 327, '<td valign="top">?two Bullhead City shots? Colorado River...? Yes-NO? very cool shot...love the light and colors. Whoooo that water is so cold....and that air is soooo hot. :)</td>', '?two Bullhead City shots? Colorado River...? Yes-NO? very cool shot...love the light and colors. Whoooo that water is so cold....and that air is soooo hot. :)', '2003-07-02 13:21:01.000000', NULL, 1),
(345164, 27066, 327, '<td valign="top">Whaaaa what a capture....</td>', 'Whaaaa what a capture....', '2003-07-02 13:21:54.000000', NULL, 1),
(345166, 27022, 7339, '<td valign="top">I love this shot. I dont know what it is but its my highest rated photo. Beautiful lighting and overall composure. I gave it an eight and would have given it a higher score if I could figure out what it was but either way I love it and will add it to my favorites as soon as i can. If you could please e-mail me what it is and how it was done. I am a big fan of long exposure shots and guessing think its possibly a flashlight being moved. Not sure what the ball is under the light point though. Great Job hope you win.</td>', 'I love this shot. I dont know what it is but its my highest rated photo. Beautiful lighting and overall composure. I gave it an eight and would have given it a higher score if I could figure out what it was but either way I love it and will add it to my favorites as soon as i can. If you could please e-mail me what it is and how it was done. I am a big fan of long exposure shots and guessing think its possibly a flashlight being moved. Not sure what the ball is under the light point though. Great Job hope you win.', '2003-07-02 13:22:19.000000', NULL, 1),
(345167, 26820, 327, '<td valign="top">Sweet bike. I have ridden a Ducati and they do fly. I think the bottom could of been cropped by a full two inches, and that would draw the eye to the rider. The color are also a bit flat. Nice, and you met the challenge.</td>', 'Sweet bike. I have ridden a Ducati and they do fly. I think the bottom could of been cropped by a full two inches, and that would draw the eye to the rider. The color are also a bit flat. Nice, and you met the challenge.', '2003-07-02 13:23:48.000000', NULL, 1),
(345168, 26374, 327, '<td valign="top">Nice, challenge is met. I do think this could of used a tighter crop. Good work.</td>', 'Nice, challenge is met. I do think this could of used a tighter crop. Good work.', '2003-07-02 13:24:46.000000', NULL, 1),
(345169, 26729, 327, '<td valign="top">Beautiful light and color. Nice speed shot, challenge is met well here. Good job. Interesting shot........</td>', 'Beautiful light and color. Nice speed shot, challenge is met well here. Good job. Interesting shot........', '2003-07-02 13:26:18.000000', NULL, 1),
