(347137, 27143, 5728, '<td valign="top">Yup that''s speed. I like the idea you''ve come up with and I think not being able to see the frame of the racket is actually very enhancing - 9.</td>', 'Yup that''s speed. I like the idea you''ve come up with and I think not being able to see the frame of the racket is actually very enhancing - 9.', '2003-07-04 18:18:48.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(347138, 26627, 8860, '<td valign="top">A tripod could have been useful to prevent shake! Good capture apart from that. [5]</td>', 'A tripod could have been useful to prevent shake! Good capture apart from that. [5]', '2003-07-04 18:18:51.000000', NULL, 1),
(347140, 26649, 5728, '<td valign="top">Now this is good! The B&amp;W gives your pic that extra push. You''ve even managed to give your motion blur on the train a lot of detail, which is difficult for blurs, well done - 9.</td>', 'Now this is good! The B&W gives your pic that extra push. You''ve even managed to give your motion blur on the train a lot of detail, which is difficult for blurs, well done - 9.', '2003-07-04 18:21:04.000000', NULL, 1),
(347143, 27018, 5728, '<td valign="top">I''m not too sure what it is but I am guessing a ride at the amusement park or something. Wonderful colors and the bright lights are not blown out at all. The crop is also very good, well done - 9.</td>', 'I''m not too sure what it is but I am guessing a ride at the amusement park or something. Wonderful colors and the bright lights are not blown out at all. The crop is also very good, well done - 9.', '2003-07-04 18:22:51.000000', NULL, 1),
(347144, 26612, 5728, '<td valign="top">The starriness on those lights are awesome. Did you set up the tripod right next to that car? Gives the impression you were leaning out the window there. Cool mix of reds and yellow, I like it - 9.</td>', 'The starriness on those lights are awesome. Did you set up the tripod right next to that car? Gives the impression you were leaning out the window there. Cool mix of reds and yellow, I like it - 9.', '2003-07-04 18:25:40.000000', NULL, 1),
(347146, 27175, 5728, '<td valign="top">This is good idea, however to depict speed I would have taken the pic whilst the speedometer was not on zero but actually but moving! Otherwise a good pic, the graininess works and the dropping is fitting - 8.</td>', 'This is good idea, however to depict speed I would have taken the pic whilst the speedometer was not on zero but actually but moving! Otherwise a good pic, the graininess works and the dropping is fitting - 8.', '2003-07-04 18:28:08.000000', NULL, 1),
(347147, 27076, 5728, '<td valign="top">This is very original and I can see movement, fast movement! Good idea - 8.</td>', 'This is very original and I can see movement, fast movement! Good idea - 8.', '2003-07-04 18:29:00.000000', NULL, 1),
(347149, 26995, 7086, '<td valign="top">To pull of a shot like this you need the static part of the image to be much clearer.</td>', 'To pull of a shot like this you need the static part of the image to be much clearer.', '2003-07-04 18:30:30.000000', NULL, 1),
(347150, 26968, 5728, '<td valign="top">I like the panorama composition, it really draws out the speed feeling. I also find that not panning this photo was a good decision - 8.</td>', 'I like the panorama composition, it really draws out the speed feeling. I also find that not panning this photo was a good decision - 8.', '2003-07-04 18:30:33.000000', NULL, 1),
(347151, 26819, 5728, '<td valign="top">Good capture, you''ve frozen your subject well. Just a little motion blur in the background to highlight movement - 8.</td>', 'Good capture, you''ve frozen your subject well. Just a little motion blur in the background to highlight movement - 8.', '2003-07-04 18:31:49.000000', NULL, 1),
(347152, 26427, 7086, '<td valign="top">The flower has been captured well, unfortunately the bee, which should be the main focus, is blurred and partially cropped.</td>', 'The flower has been captured well, unfortunately the bee, which should be the main focus, is blurred and partially cropped.', '2003-07-04 18:32:57.000000', NULL, 1),
(347153, 26746, 7086, '<td valign="top">Well captured detail, the blown highlights let it down slightly.</td>', 'Well captured detail, the blown highlights let it down slightly.', '2003-07-04 18:34:59.000000', NULL, 1),
(347156, 27088, 7086, '<td valign="top">A tighter crop may have been better as there''s alot of empty space above and to the left.</td>', 'A tighter crop may have been better as there''s alot of empty space above and to the left.', '2003-07-04 18:36:46.000000', NULL, 1),
(347160, 26871, 5728, '<td valign="top">I see you have tried to depict speed in two ways; one showing the speed on the speedometer and two with a motion blur on the speedometer and rev counter. The idea is good, although I would probably have prefered seeing everything focused and detailed. Interesting effect though.</td>', 'I see you have tried to depict speed in two ways; one showing the speed on the speedometer and two with a motion blur on the speedometer and rev counter. The idea is good, although I would probably have prefered seeing everything focused and detailed. Interesting effect though.', '2003-07-04 18:38:27.000000', NULL, 1),
(347161, 27008, 6870, '<td valign="top">Clever idea. I like the almost silhouette of these flowers.</td>', 'Clever idea. I like the almost silhouette of these flowers.', '2003-07-04 18:39:05.000000', NULL, 1),
(347163, 26662, 6870, '<td valign="top">Delightfully energetic! 9</td>', 'Delightfully energetic! 9', '2003-07-04 18:39:39.000000', NULL, 1),
(347164, 26740, 5728, '<td valign="top">You''ve shown movement and speed for sure, but somehow the color mix isn''t working for me. Looks kind of psychedelic actually.</td>', 'You''ve shown movement and speed for sure, but somehow the color mix isn''t working for me. Looks kind of psychedelic actually.', '2003-07-04 18:40:27.000000', NULL, 1),
(347167, 27201, 5728, '<td valign="top">I saw a poster like this once. It is interesting for sure, but different. It doesn''t really work for me although I have to say the idea is good!</td>', 'I saw a poster like this once. It is interesting for sure, but different. It doesn''t really work for me although I have to say the idea is good!', '2003-07-04 18:42:05.000000', NULL, 1),
(347168, 26528, 7086, '<td valign="top">Good image but reliant on the viewer knowing about a Corvette to imply speed. The flag emblem is slightly soft and given that you have created a symetrical image the reflection of the light source is slightly off.</td>', 'Good image but reliant on the viewer knowing about a Corvette to imply speed. The flag emblem is slightly soft and given that you have created a symetrical image the reflection of the light source is slightly off.', '2003-07-04 18:42:36.000000', NULL, 1),
(347172, 26804, 7086, '<td valign="top">I can''t work out this out and the title gives no clues. I ssume you have used the camera flash and looking at the lack of light lower left you may have blocked it. The main object within the image is out of focus.</td>', 'I can''t work out this out and the title gives no clues. I ssume you have used the camera flash and looking at the lack of light lower left you may have blocked it. The main object within the image is out of focus.', '2003-07-04 18:47:40.000000', NULL, 1),
(347175, 26732, 7086, '<td valign="top">Llighting from the camera view may be better IMO, slightly soft image.</td>', 'Llighting from the camera view may be better IMO, slightly soft image.', '2003-07-04 18:50:24.000000', NULL, 1),
(347177, 26810, 7086, '<td valign="top">A static needle doesn''t indicate acceleration IMO.</td>', 'A static needle doesn''t indicate acceleration IMO.', '2003-07-04 18:51:48.000000', NULL, 1),
(347179, 26700, 7086, '<td valign="top">The lighter blocks spoil the image.</td>', 'The lighter blocks spoil the image.', '2003-07-04 18:54:15.000000', NULL, 1),
(347181, 26366, 7086, '<td valign="top">Soft and over-exposed, but does give a sense of excitement.</td>', 'Soft and over-exposed, but does give a sense of excitement.', '2003-07-04 18:56:11.000000', NULL, 1),
(347182, 26964, 4494, '<td valign="top">Few times that a border looks good (great) and really enhances the shot.  Nice job, I like the tone of the sky, it fits well with the silloutte.</td>', 'Few times that a border looks good (great) and really enhances the shot.  Nice job, I like the tone of the sky, it fits well with the silloutte.', '2003-07-04 18:56:36.000000', NULL, 1),
(347183, 26801, 7086, '<td valign="top">Very nice absract, almost painted feel to it. Doesn''t shout speed though.</td>', 'Very nice absract, almost painted feel to it. Doesn''t shout speed though.', '2003-07-04 18:57:43.000000', NULL, 1),
(347184, 26740, 7086, '<td valign="top">A slightly faster shutter and centralising the crop could have made more of this.</td>', 'A slightly faster shutter and centralising the crop could have made more of this.', '2003-07-04 18:59:08.000000', NULL, 1),
(347185, 26911, 4494, '<td valign="top">Wow really gives the feeling of speed.  Nice abstract shot, colors are great also.</td>', 'Wow really gives the feeling of speed.  Nice abstract shot, colors are great also.', '2003-07-04 18:59:45.000000', NULL, 1),
(347186, 26662, 4494, '<td valign="top">Looks like the car in front of the cab hit his brakes when he went past, and it left that big red streak on the cab.</td>', 'Looks like the car in front of the cab hit his brakes when he went past, and it left that big red streak on the cab.', '2003-07-04 19:04:07.000000', NULL, 1),
(347187, 27190, 7086, '<td valign="top">Good image, slightly offcentre and soft background though.</td>', 'Good image, slightly offcentre and soft background though.', '2003-07-04 19:04:46.000000', NULL, 1),
(347190, 27134, 4494, '<td valign="top">I''ve never seen a sign like that before.  I like the "texture" of this shot and the low light/dark coloring.</td>', 'I''ve never seen a sign like that before.  I like the "texture" of this shot and the low light/dark coloring.', '2003-07-04 19:07:28.000000', NULL, 1),
(347192, 27101, 7086, '<td valign="top">Nothing really in focus but it works well</td>', 'Nothing really in focus but it works well', '2003-07-04 19:08:25.000000', NULL, 1),
(347195, 27160, 4494, '<td valign="top">Nice "streak" behind the car.  The car itself could be a little lighter.  Nice cropping.</td>', 'Nice "streak" behind the car.  The car itself could be a little lighter.  Nice cropping.', '2003-07-04 19:12:48.000000', NULL, 1),
(347197, 26957, 4494, '<td valign="top">Very cool, and original shot.  Nice one!  The lighting on the hand is really great.</td>', 'Very cool, and original shot.  Nice one!  The lighting on the hand is really great.', '2003-07-04 19:14:43.000000', NULL, 1),
(347204, 27089, 4494, '<td valign="top">Is that your car that you parked there to match the tire marks on the road?  Pretty good idea, but kinda dangerous since the car is sticking out into the road!</td>', 'Is that your car that you parked there to match the tire marks on the road?  Pretty good idea, but kinda dangerous since the car is sticking out into the road!', '2003-07-04 19:25:58.000000', NULL, 1),
(347205, 27022, 4494, '<td valign="top">What is the thing below the "bullet"?  Looks like a bowl?  Pretty interesting shot and does give a nice feel of speed.</td>', 'What is the thing below the "bullet"?  Looks like a bowl?  Pretty interesting shot and does give a nice feel of speed.', '2003-07-04 19:27:48.000000', NULL, 1),
(347208, 27099, 4494, '<td valign="top">Should have had the sprocket turning also to give a better feel of speed.</td>', 'Should have had the sprocket turning also to give a better feel of speed.', '2003-07-04 19:29:04.000000', NULL, 1),
(347209, 27076, 4494, '<td valign="top">Very cool shot, those high speed printing presses (?) always amaze me.  I''ve always wondered what would happen if you took a knife and sliced the paper while that thing is running, how much of a pile on the floor you''d have in just a few seconds.</td>', 'Very cool shot, those high speed printing presses (?) always amaze me.  I''ve always wondered what would happen if you took a knife and sliced the paper while that thing is running, how much of a pile on the floor you''d have in just a few seconds.', '2003-07-04 19:31:51.000000', NULL, 1),
(347210, 26733, 4494, '<td valign="top">Those bugs are so fun to shoot because they just hover like that so it''s easy to get a shot of them.  Great job, except I would have shown a little more above and below it.</td>', 'Those bugs are so fun to shoot because they just hover like that so it''s easy to get a shot of them.  Great job, except I would have shown a little more above and below it.', '2003-07-04 19:34:11.000000', NULL, 1),
(347211, 26793, 4494, '<td valign="top">Great job the white dog really stands out nicely against the dark green background.</td>', 'Great job the white dog really stands out nicely against the dark green background.', '2003-07-04 19:36:15.000000', NULL, 1),
(347213, 27105, 4494, '<td valign="top">Excellent!  What would have been a little better is, shooting the shot from a few more feet to the right.  That would keep the bench in the same place but position the water fall more the right (not as centered).  Very nice!</td>', 'Excellent!  What would have been a little better is, shooting the shot from a few more feet to the right.  That would keep the bench in the same place but position the water fall more the right (not as centered).  Very nice!', '2003-07-04 19:38:41.000000', NULL, 1),
(347214, 27194, 4494, '<td valign="top">It''s a little too small.</td>', 'It''s a little too small.', '2003-07-04 19:39:01.000000', NULL, 1),
(347216, 26943, 4494, '<td valign="top">EXCELLENT shot!  I love it the composition and lighting.   Looks you took this right at dusk so the lights are on but the sky isn''t too dark yet.  Nice one!</td>', 'EXCELLENT shot!  I love it the composition and lighting.   Looks you took this right at dusk so the lights are on but the sky isn''t too dark yet.  Nice one!', '2003-07-04 19:42:20.000000', NULL, 1),
(347217, 27173, 4494, '<td valign="top">This is really interesting.  I''m wondering how you get the light to look that way be the girl is still in focus.  Good job, very cool.</td>', 'This is really interesting.  I''m wondering how you get the light to look that way be the girl is still in focus.  Good job, very cool.', '2003-07-04 19:44:23.000000', NULL, 1),
(347222, 26374, 4494, '<td valign="top">Awesome shot.  I love the perfect focus on the bird, the reflection, the positioning of the bird in the shot, and the great green water.  Great job!</td>', 'Awesome shot.  I love the perfect focus on the bird, the reflection, the positioning of the bird in the shot, and the great green water.  Great job!', '2003-07-04 20:05:21.000000', NULL, 1),
(347223, 27137, 4494, '<td valign="top">What did you do to the bottom of the picture?  It doesn''t really help and looks a little weird.  Nice job on the leaving just a slight bit of color.</td>', 'What did you do to the bottom of the picture?  It doesn''t really help and looks a little weird.  Nice job on the leaving just a slight bit of color.', '2003-07-04 20:06:56.000000', NULL, 1),
(347228, 27031, 4494, '<td valign="top">Looks like you added a filter effect to this?  If not, I''m not sure why it looks like this.  Maybe you had to crop it too much?  In addition it is tilted a LOT to the left.</td>', 'Looks like you added a filter effect to this?  If not, I''m not sure why it looks like this.  Maybe you had to crop it too much?  In addition it is tilted a LOT to the left.', '2003-07-04 20:10:11.000000', NULL, 1),
(347230, 27110, 8865, '<td valign="top">Great colors &amp; quality. Too bad about that persons head down there. But what can ya do when there is a bunch of people eh? =) I don''t have really anything to critize about this picture, except maybe I would have liked to have seen the still lights not overlapping the ride. But still good pic! =)</td>', 'Great colors & quality. Too bad about that persons head down there. But what can ya do when there is a bunch of people eh? =) I don''t have really anything to critize about this picture, except maybe I would have liked to have seen the still lights not overlapping the ride. But still good pic! =)', '2003-07-04 20:13:13.000000', NULL, 1),
(347231, 27199, 4494, '<td valign="top">YEAHH!  Great shot!  I''ll be taking my own pics later tonight!  GREAT job on this shot the cropping is fantastic and the location of the explosion is perfect.</td>', 'YEAHH!  Great shot!  I''ll be taking my own pics later tonight!  GREAT job on this shot the cropping is fantastic and the location of the explosion is perfect.', '2003-07-04 20:13:58.000000', NULL, 1),
(347234, 27200, 4494, '<td valign="top">Nice "life-like" colors, and the background is kind of interesting.  Good job with the boat placement also.</td>', 'Nice "life-like" colors, and the background is kind of interesting.  Good job with the boat placement also.', '2003-07-04 20:15:38.000000', NULL, 1),
(347238, 27195, 8865, '<td valign="top">It''s sort of hard to see that it is spinning, in the middle it it looks more like shaved metal sitting still. Not sure what those white speckles are on the black there. But those could be easily cleaned up in photoshop =)</td>', 'It''s sort of hard to see that it is spinning, in the middle it it looks more like shaved metal sitting still. Not sure what those white speckles are on the black there. But those could be easily cleaned up in photoshop =)', '2003-07-04 20:18:42.000000', NULL, 1),
(347243, 27105, 8865, '<td valign="top">Nice photo. The water looks great that soft looking. I like the lonely bench there, but I''m not sure what that white thing is there beside it. But that could be easily edited out =)</td>', 'Nice photo. The water looks great that soft looking. I like the lonely bench there, but I''m not sure what that white thing is there beside it. But that could be easily edited out =)', '2003-07-04 20:21:23.000000', NULL, 1),
(347251, 26372, 8865, '<td valign="top">That''s a great picture. How did the red lights get so high up there? Weird. But very interesting. The street lights look like they''re floating in the middle of no where. I like that. I also like how the road leads you to a far off distance. The 10 there looks good as well. Good job &amp; good luck! =)</td>', 'That''s a great picture. How did the red lights get so high up there? Weird. But very interesting. The street lights look like they''re floating in the middle of no where. I like that. I also like how the road leads you to a far off distance. The 10 there looks good as well. Good job & good luck! =)', '2003-07-04 20:28:45.000000', NULL, 1),
(347252, 26932, 8865, '<td valign="top">Nice image.  Great quality, colors, border goes good, but I would have liked to have seen more of the splash she is making though. But good one =)</td>', 'Nice image.  Great quality, colors, border goes good, but I would have liked to have seen more of the splash she is making though. But good one =)', '2003-07-04 20:30:13.000000', NULL, 1),
(347253, 27187, 8865, '<td valign="top">Hmm I''m not sure what is getting mixed up. But I like the colors in this picture, blue &amp; yellow go well together.</td>', 'Hmm I''m not sure what is getting mixed up. But I like the colors in this picture, blue & yellow go well together.', '2003-07-04 20:32:17.000000', NULL, 1),
(347254, 26890, 8865, '<td valign="top">It seems a tad dark, that it makes a couple horses blend in with the one it is running beside, but that could be my monitor. I like how the white/tan one stands out though. Nice capture. =)</td>', 'It seems a tad dark, that it makes a couple horses blend in with the one it is running beside, but that could be my monitor. I like how the white/tan one stands out though. Nice capture. =)', '2003-07-04 20:34:37.000000', NULL, 1),
(347255, 27076, 8865, '<td valign="top">Now that is cruising. I love all the different shades of grey. Great quality, nice &amp; clean. Good one =)</td>', 'Now that is cruising. I love all the different shades of grey. Great quality, nice & clean. Good one =)', '2003-07-04 20:36:01.000000', NULL, 1),
(347256, 26995, 8865, '<td valign="top">It looks a little pixelated [sp?], but I''m not sure what kind of camera you use. It''s a great image. I like how there is no color but only the light &amp; people in the train. Good luck.</td>', 'It looks a little pixelated [sp?], but I''m not sure what kind of camera you use. It''s a great image. I like how there is no color but only the light & people in the train. Good luck.', '2003-07-04 20:37:35.000000', NULL, 1),
(347257, 26634, 8865, '<td valign="top">You probably got lots of "where''s the speed?" comments.  Cute dog &amp; photo though =)</td>', 'You probably got lots of "where''s the speed?" comments.  Cute dog & photo though =)', '2003-07-04 20:39:39.000000', NULL, 1),
(347274, 26988, 2158, '<td valign="top">I like this photo, but I''m not sure it''s right for this challenge.</td>', 'I like this photo, but I''m not sure it''s right for this challenge.', '2003-07-04 21:05:26.000000', NULL, 1),
(347290, 27201, 2158, '<td valign="top">I think this might work better if there was a bit more contrast between the subject and the background.</td>', 'I think this might work better if there was a bit more contrast between the subject and the background.', '2003-07-04 21:16:19.000000', NULL, 1),
(347305, 26978, 1570, '<td valign="top">this is not art... 1.</td>', 'this is not art... 1.', '2003-07-04 21:45:27.000000', NULL, 1),
(347307, 27093, 1570, '<td valign="top">they look very happy, i love the dynamics of this picture...  i wish that green cover was out of the picture, but still , i like it a lot...  even the tilt works for me... 7.</td>', 'they look very happy, i love the dynamics of this picture...  i wish that green cover was out of the picture, but still , i like it a lot...  even the tilt works for me... 7.', '2003-07-04 21:53:12.000000', NULL, 1),
(347308, 27201, 1570, '<td valign="top">too fast for me...</td>', 'too fast for me...', '2003-07-04 21:54:16.000000', NULL, 1),
(347310, 26734, 1570, '<td valign="top">what a fascinating take on this challenge! the picture itself looks very interesting in a strange way - to me, anyway...8.</td>', 'what a fascinating take on this challenge! the picture itself looks very interesting in a strange way - to me, anyway...8.', '2003-07-04 21:58:01.000000', NULL, 1),
(347319, 26980, 2792, '<td valign="top">I don''t see "speed" conveyed at all.  Sorry.</td>', 'I don''t see "speed" conveyed at all.  Sorry.', '2003-07-04 22:47:19.000000', NULL, 1),
(347321, 26746, 2792, '<td valign="top">The minute hand is overexposed.  The cropping on the right is a little tight; would have liked to have seen the "15".  Still, nice job.</td>', 'The minute hand is overexposed.  The cropping on the right is a little tight; would have liked to have seen the "15".  Still, nice job.', '2003-07-04 22:49:32.000000', NULL, 1),
(347324, 27136, 2792, '<td valign="top">Nice candid.  The finish line looks a little odd (exposure perhaps?).</td>', 'Nice candid.  The finish line looks a little odd (exposure perhaps?).', '2003-07-04 22:55:13.000000', NULL, 1),
(347326, 27176, 2792, '<td valign="top">Great idea!  Shows speed well. Adjusting levels, brightness/contrast might improve it as well.  =-)</td>', 'Great idea!  Shows speed well. Adjusting levels, brightness/contrast might improve it as well.  =-)', '2003-07-04 23:02:07.000000', NULL, 1),
(347351, 27196, 8865, '<td valign="top">Very good. The quality is outstanding. I like the hint of red in there. Too bad the top lights were not turned on. Excellent photo. =)</td>', 'Very good. The quality is outstanding. I like the hint of red in there. Too bad the top lights were not turned on. Excellent photo. =)', '2003-07-05 01:22:57.000000', NULL, 1),
(347352, 26374, 8865, '<td valign="top">That looks surreal. It''s a really great photo. I like the green water, it goes nicely with the duck. The reflection adds so much to the photo. Great shot, and quality.</td>', 'That looks surreal. It''s a really great photo. I like the green water, it goes nicely with the duck. The reflection adds so much to the photo. Great shot, and quality.', '2003-07-05 01:23:11.000000', NULL, 1),
(347353, 26744, 8865, '<td valign="top">Nice Photo. I like the colors that turned up. The quality is excellent. The only things that disctract me are the car sitting on the other side of the road. But I guess you can''t go tell the driver to move it ;o) I also find the lit up door on the far left a bit disctracting. But that could be cropped out if needed =) Good luck!</td>', 'Nice Photo. I like the colors that turned up. The quality is excellent. The only things that disctract me are the car sitting on the other side of the road. But I guess you can''t go tell the driver to move it ;o) I also find the lit up door on the far left a bit disctracting. But that could be cropped out if needed =) Good luck!', '2003-07-05 01:23:45.000000', NULL, 1),
(347376, 27173, 9711, '<td valign="top">beautiful frame!</td>', 'beautiful frame!', '2003-07-05 03:33:33.000000', NULL, 1),
(347379, 27047, 9711, '<td valign="top">beautiful picture, shows speed in art, and creation!</td>', 'beautiful picture, shows speed in art, and creation!', '2003-07-05 03:36:17.000000', NULL, 1),
(347380, 27180, 9711, '<td valign="top">a very nice different meaning of the speed!</td>', 'a very nice different meaning of the speed!', '2003-07-05 03:36:48.000000', NULL, 1),
(347383, 27003, 9711, '<td valign="top">great subject, but i would have choose my angle another way!</td>', 'great subject, but i would have choose my angle another way!', '2003-07-05 04:00:27.000000', NULL, 1),
(347398, 26634, 9809, '<td valign="top">I absolutely love the photo, but I''m at a loss as to how this relates to "speed." Too bad the dog''s head it a bit blown out.</td>', 'I absolutely love the photo, but I''m at a loss as to how this relates to "speed." Too bad the dog''s head it a bit blown out.', '2003-07-05 07:07:35.000000', NULL, 1),
(347403, 26746, 7743, '<td valign="top">This image is very crisp and the off-centre placement works to emphasize the second hand.  This is a novel approach to the challenge.    In addition to placing the watch off-centre did you also try to put it a little on the diagonal?<br/> <br/>Unfortunately this image has very little impact.</td>', 'This image is very crisp and the off-centre placement works to emphasize the second hand.  This is a novel approach to the challenge.    In addition to placing the watch off-centre did you also try to put it a little on the diagonal? Unfortunately this image has very little impact.', '2003-07-05 07:45:55.000000', NULL, 1),
(347404, 27201, 7743, '<td valign="top">This is a very interesting twist.  The object is well placed within the frame though maybe a little too invisible.  This could be due to the yellow filter/background used.  Did you try other colours?</td>', 'This is a very interesting twist.  The object is well placed within the frame though maybe a little too invisible.  This could be due to the yellow filter/background used.  Did you try other colours?', '2003-07-05 07:48:31.000000', NULL, 1),
(347405, 26699, 9854, '<td valign="top">I like the way the streetlamps appear like asterisks.</td>', 'I like the way the streetlamps appear like asterisks.', '2003-07-05 07:49:08.000000', NULL, 1),
(347406, 26852, 7743, '<td valign="top">The composition works with the subject placed well off-center and the blurr lines on the diagonal.  Exposure seems to be correct though the lighting seems to be a bit yellow.<br/> <br/>I''m having a hard time seeing the speed applied to  the telephone/network cable.  Maybe if the right side of the cable also had blur streaks this would work.  Did you try the reverse effect where the background was sharp and the cable was moving through the frame?</td>', 'The composition works with the subject placed well off-center and the blurr lines on the diagonal.  Exposure seems to be correct though the lighting seems to be a bit yellow. I''m having a hard time seeing the speed applied to  the telephone/network cable.  Maybe if the right side of the cable also had blur streaks this would work.  Did you try the reverse effect where the background was sharp and the cable was moving through the frame?', '2003-07-05 07:57:16.000000', NULL, 1),
(347407, 27164, 9854, '<td valign="top">Great idea....effective in conveying a sense of speed alongside an almost static reference</td>', 'Great idea....effective in conveying a sense of speed alongside an almost static reference', '2003-07-05 07:57:38.000000', NULL, 1),
