INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(348850, 27146, 917, '<td valign="top">Its really good, but I cant help feeling that more could have been made of the chains, and the composition just doenst feel right, possibly because the top right girl is looking out of frame.</td>', 'Its really good, but I cant help feeling that more could have been made of the chains, and the composition just doenst feel right, possibly because the top right girl is looking out of frame.', '2003-07-07 09:45:37.000000', NULL, 1),
(348852, 27202, 917, '<td valign="top">Cant decide if Im missing something here, but I just dont like it. Composition is OK, but the subject has nothing to do with speed, and its too bright. I like the feeling of dissonnace here.</td>', 'Cant decide if Im missing something here, but I just dont like it. Composition is OK, but the subject has nothing to do with speed, and its too bright. I like the feeling of dissonnace here.', '2003-07-07 09:48:56.000000', NULL, 1),
(348853, 26992, 917, '<td valign="top">Needs zooming in, send them round again and get them to bunch up a bit next time.</td>', 'Needs zooming in, send them round again and get them to bunch up a bit next time.', '2003-07-07 09:52:41.000000', NULL, 1),
(348857, 27138, 917, '<td valign="top">The first decent car pic Ive seen so far.</td>', 'The first decent car pic Ive seen so far.', '2003-07-07 09:55:35.000000', NULL, 1),
(348859, 26887, 917, '<td valign="top">At fist I thought this was a bad picture of a monster truck, but its actually quite a clever pic of a toy making it look huge. Perhaps a bit more sharpness on the body.</td>', 'At fist I thought this was a bad picture of a monster truck, but its actually quite a clever pic of a toy making it look huge. Perhaps a bit more sharpness on the body.', '2003-07-07 09:57:46.000000', NULL, 1),
(348863, 27105, 917, '<td valign="top">White thing in front of the chair needs moving, something wrong happening at the top (perhaps the white border hasnt helped). Otherwise its quite good.</td>', 'White thing in front of the chair needs moving, something wrong happening at the top (perhaps the white border hasnt helped). Otherwise its quite good.', '2003-07-07 10:02:28.000000', NULL, 1),
(348865, 26733, 917, '<td valign="top">Excellent, one of the few shots on DPC that are hard to do and well executed. I often struggle with glare on this species. Oh and congrats on not calling it a bug, that one really drives me mad.</td>', 'Excellent, one of the few shots on DPC that are hard to do and well executed. I often struggle with glare on this species. Oh and congrats on not calling it a bug, that one really drives me mad.', '2003-07-07 10:08:35.000000', NULL, 1),
(348866, 27163, 2458, '<td valign="top">does not meet requirement</td>', 'does not meet requirement', '2003-07-07 10:09:48.000000', NULL, 1),
(348875, 26927, 917, '<td valign="top">Methinks this is going to score quite low. You either dont care about the dpc audience, or you have misjudged them completely. Either way, you wount get any useful feedback here.</td>', 'Methinks this is going to score quite low. You either dont care about the dpc audience, or you have misjudged them completely. Either way, you wount get any useful feedback here.', '2003-07-07 10:25:34.000000', NULL, 1),
(348877, 27071, 917, '<td valign="top">Dunno what to make of this, its so obviously fake. But its quite a nice quirky image. I think I like it, but not a huge amount.</td>', 'Dunno what to make of this, its so obviously fake. But its quite a nice quirky image. I think I like it, but not a huge amount.', '2003-07-07 10:30:10.000000', NULL, 1),
(348881, 26372, 917, '<td valign="top">Perfect apart from the white light on the extreme right, probably a reflection of the following cars headlights.</td>', 'Perfect apart from the white light on the extreme right, probably a reflection of the following cars headlights.', '2003-07-07 10:32:36.000000', NULL, 1),
(348886, 27142, 1202, '<td valign="top">I am one of those that thinks to show speed, it needs some blur, so panning with the boarder and a slower shutter, would have made it a lot better.   6</td>', 'I am one of those that thinks to show speed, it needs some blur, so panning with the boarder and a slower shutter, would have made it a lot better.   6', '2003-07-07 10:34:39.000000', NULL, 1),
(348888, 27180, 1202, '<td valign="top">I like your originality.   You have shown the speed of your machine very well, and its a nicely executed shot too.  7</td>', 'I like your originality.   You have shown the speed of your machine very well, and its a nicely executed shot too.  7', '2003-07-07 10:36:28.000000', NULL, 1),
(348895, 26988, 1202, '<td valign="top">This picture shows a lot of movement without having any blur.  A well executed shot.  Cropping to just show his reflection in the speeding bus is pretty amazing also.  8</td>', 'This picture shows a lot of movement without having any blur.  A well executed shot.  Cropping to just show his reflection in the speeding bus is pretty amazing also.  8', '2003-07-07 10:40:24.000000', NULL, 1),
(348897, 27047, 917, '<td valign="top">Nah, mine is better, and my bird has nicer hands, and she can actually play the piano (dont kid me that hands that close together are actually playing a tune), and my title wasnt the name of a rather ugly British Leyland rust bucket from the 70''s/80''s, and I used colour,  and I used a better angle, and, um, thats all I can think of right now. See you on the 5s, ''The Other Piano Photograph Taker''</td>', 'Nah, mine is better, and my bird has nicer hands, and she can actually play the piano (dont kid me that hands that close together are actually playing a tune), and my title wasnt the name of a rather ugly British Leyland rust bucket from the 70''s/80''s, and I used colour,  and I used a better angle, and, um, thats all I can think of right now. See you on the 5s, ''The Other Piano Photograph Taker''', '2003-07-07 10:40:57.000000', NULL, 1),
(348900, 27010, 1202, '<td valign="top">Yours is a neat picture but it doesn''t really make me think of speed.   What is it anyway?  5</td>', 'Yours is a neat picture but it doesn''t really make me think of speed.   What is it anyway?  5', '2003-07-07 10:43:12.000000', NULL, 1),
(348904, 26805, 1202, '<td valign="top">A simple picture, meets the challenge, but has low interest factor for me.   4</td>', 'A simple picture, meets the challenge, but has low interest factor for me.   4', '2003-07-07 10:46:23.000000', NULL, 1),
(348905, 27159, 7743, '<td valign="top">Good representation of speed but the image is overexposed by at least 1 full stop.</td>', 'Good representation of speed but the image is overexposed by at least 1 full stop.', '2003-07-07 10:47:18.000000', NULL, 1),
(348908, 26979, 1202, '<td valign="top">An interesting shot.  I feel it is overall too gray and needs more definition and contrast.  IMO the border didn''t save it either.  4</td>', 'An interesting shot.  I feel it is overall too gray and needs more definition and contrast.  IMO the border didn''t save it either.  4', '2003-07-07 10:49:27.000000', NULL, 1),
(348909, 26770, 917, '<td valign="top">Good timing, but theres too much crowd, and the background is too cluttered.</td>', 'Good timing, but theres too much crowd, and the background is too cluttered.', '2003-07-07 10:50:20.000000', NULL, 1),
(348910, 27056, 7743, '<td valign="top">Good sense of motion in this image.  The hand is a bit distracting though.  Did you try  without the hand in the frame?  Showing more of the raquet and less of the hand?</td>', 'Good sense of motion in this image.  The hand is a bit distracting though.  Did you try  without the hand in the frame?  Showing more of the raquet and less of the hand?', '2003-07-07 10:50:47.000000', NULL, 1),
(348912, 26407, 7743, '<td valign="top">Good sensation of speed is implied by this image.  The white line in the top right is distracting.  Did you try shots with more of the car and no white line?</td>', 'Good sensation of speed is implied by this image.  The white line in the top right is distracting.  Did you try shots with more of the car and no white line?', '2003-07-07 10:52:52.000000', NULL, 1),
(348913, 27069, 7743, '<td valign="top">I guess you might see the world this way if you were on speed.  Interesting interpretation of the challenge.</td>', 'I guess you might see the world this way if you were on speed.  Interesting interpretation of the challenge.', '2003-07-07 10:54:59.000000', NULL, 1),
(348915, 27176, 7743, '<td valign="top">The speed of losing cash.....</td>', 'The speed of losing cash.....', '2003-07-07 10:57:14.000000', NULL, 1),
(348916, 26964, 2337, '<td valign="top">Excellent shot!  I imagine your seeing a few "doesn''t meet the challenge" from folks that use too much speed when voting... This made me think a while!  You get a 10 from me :)</td>', 'Excellent shot!  I imagine your seeing a few "doesn''t meet the challenge" from folks that use too much speed when voting... This made me think a while!  You get a 10 from me :)', '2003-07-07 10:59:00.000000', NULL, 1),
(348935, 27050, 1202, '<td valign="top">Your picture is confusing to me, I am unable to tell what it is and how it might relate to speed.   It looks as though you only moved your camera horizontally to blur the lights in the background.   I guess the speed of your movement is what you were trying to show.  3</td>', 'Your picture is confusing to me, I am unable to tell what it is and how it might relate to speed.   It looks as though you only moved your camera horizontally to blur the lights in the background.   I guess the speed of your movement is what you were trying to show.  3', '2003-07-07 11:27:01.000000', NULL, 1),
(348938, 27173, 1202, '<td valign="top">An interesting picture.  I feel that if the little girl were intently looking into the light and the patterns she is making, it would be more interesting.  As it is her expression doesn''t actually fit her actions and it looks too staged.  6<br/><br/><i>Message edited by author 2003-07-15 21:04:16.</i></td>', 'An interesting picture.  I feel that if the little girl were intently looking into the light and the patterns she is making, it would be more interesting.  As it is her expression doesn''t actually fit her actions and it looks too staged.  6', '2003-07-07 11:30:03.000000', '2003-07-15 22:04:16.000000', 1),
(348939, 26945, 1202, '<td valign="top">The downward tilt, the attitude of the rider, no spkes,and the blur of the background all add the flavor of speed to your picture.   The colors are pretty flat and a real WOW factor is absent though.   6</td>', 'The downward tilt, the attitude of the rider, no spkes,and the blur of the background all add the flavor of speed to your picture.   The colors are pretty flat and a real WOW factor is absent though.   6', '2003-07-07 11:32:24.000000', NULL, 1),
(348941, 27204, 1202, '<td valign="top">Very nice expression of speed here.  I like the lighting too.  7</td>', 'Very nice expression of speed here.  I like the lighting too.  7', '2003-07-07 11:33:36.000000', NULL, 1),
(348949, 27075, 8610, '<td valign="top">Best car in the world :D  8 fo that</td>', 'Best car in the world :D  8 fo that', '2003-07-07 11:50:53.000000', NULL, 1),
(348951, 26998, 8610, '<td valign="top">Fallegur bíll</td>', 'Fallegur bíll', '2003-07-07 11:52:42.000000', NULL, 1),
(348954, 26372, 8610, '<td valign="top">Hvalfjörður.. og er þetta þá ekki EikiDigi :D - 10 fyrir ættjörðina</td>', 'Hvalfjörður.. og er þetta þá ekki EikiDigi :D - 10 fyrir ættjörðina', '2003-07-07 11:53:36.000000', NULL, 1),
(348971, 27103, 1202, '<td valign="top">I don''t get speed from this at all, it looks more like a falling thing.  Sorry! 3</td>', 'I don''t get speed from this at all, it looks more like a falling thing.  Sorry! 3', '2003-07-07 12:18:37.000000', NULL, 1),
(348974, 26992, 5822, '<td valign="top">Color and clarity are really good, but I don''t get the feeling of speed here as it''s more implied. I think had you used the panning technique with a slower shutter speed the background would have been more blurred and would have conveyed speed better. You can even see the spokes in the wheels suggesting to me they were going fairly slow at the time you exposed the shot.</td>', 'Color and clarity are really good, but I don''t get the feeling of speed here as it''s more implied. I think had you used the panning technique with a slower shutter speed the background would have been more blurred and would have conveyed speed better. You can even see the spokes in the wheels suggesting to me they were going fairly slow at the time you exposed the shot.', '2003-07-07 12:19:36.000000', NULL, 1),
(348975, 27085, 1202, '<td valign="top">I don''t get speed out of this, with the tail lights so bright it appears that all of the trafic is stopping.   Just the opposite of speeding/speed.  3</td>', 'I don''t get speed out of this, with the tail lights so bright it appears that all of the trafic is stopping.   Just the opposite of speeding/speed.  3', '2003-07-07 12:20:09.000000', NULL, 1),
(348976, 27069, 1202, '<td valign="top">Speed or speed, that is the question.  I don''t see the motion or moving type here, and I think that is what was intended for the challenge.  3</td>', 'Speed or speed, that is the question.  I don''t see the motion or moving type here, and I think that is what was intended for the challenge.  3', '2003-07-07 12:21:38.000000', NULL, 1),
(348978, 26732, 1202, '<td valign="top">A knowledgeable  car person couldn''t help but think of speed here, but what if the viewer knew nothing of fast cars?  5</td>', 'A knowledgeable  car person couldn''t help but think of speed here, but what if the viewer knew nothing of fast cars?  5', '2003-07-07 12:23:11.000000', NULL, 1),
(348982, 27182, 1202, '<td valign="top">You not only show the movement of the speeding bike but the thrill of going fast.   Super job.  10</td>', 'You not only show the movement of the speeding bike but the thrill of going fast.   Super job.  10', '2003-07-07 12:27:33.000000', NULL, 1),
(348983, 26991, 1202, '<td valign="top">You got it pretty well here.   Nice effect.  7</td>', 'You got it pretty well here.   Nice effect.  7', '2003-07-07 12:28:54.000000', NULL, 1),
(348985, 27059, 1202, '<td valign="top">Pretty colors but it doesn''t really show speed to me, more just camera movement.  4</td>', 'Pretty colors but it doesn''t really show speed to me, more just camera movement.  4', '2003-07-07 12:29:49.000000', NULL, 1),
(348988, 26932, 1202, '<td valign="top">Extra nice in my book.  excellent composition with the red boat in the background.  9</td>', 'Extra nice in my book.  excellent composition with the red boat in the background.  9', '2003-07-07 12:31:32.000000', NULL, 1),
(348991, 26374, 917, '<td valign="top">Needs cropping off the top, to make more use of the reflection.</td>', 'Needs cropping off the top, to make more use of the reflection.', '2003-07-07 12:32:56.000000', NULL, 1),
(348993, 27055, 1202, '<td valign="top">Tricky little picture.  I think I like it better in landscape.  6</td>', 'Tricky little picture.  I think I like it better in landscape.  6', '2003-07-07 12:33:01.000000', NULL, 1),
(348996, 27163, 1202, '<td valign="top">Beautiful picture but I don''t get the relationship to any type of speed.  Please explain after the challenge.  4</td>', 'Beautiful picture but I don''t get the relationship to any type of speed.  Please explain after the challenge.  4', '2003-07-07 12:35:54.000000', NULL, 1),
(349001, 27022, 1202, '<td valign="top">A very nicely done picture.  I am unfamiliar with the subject though, so it is very hard for me to judge.   Needs to ge more self explanitory.  4</td>', 'A very nicely done picture.  I am unfamiliar with the subject though, so it is very hard for me to judge.   Needs to ge more self explanitory.  4', '2003-07-07 12:41:48.000000', NULL, 1),
(349002, 27159, 1202, '<td valign="top">Much too bad it is so overexposed.  You have shown the speed of the train well.  5</td>', 'Much too bad it is so overexposed.  You have shown the speed of the train well.  5', '2003-07-07 12:43:50.000000', NULL, 1),
(349003, 26964, 917, '<td valign="top">Lose the bush, level the horizon, raise the brats chin, submit this to a more relevant challenge subject.</td>', 'Lose the bush, level the horizon, raise the brats chin, submit this to a more relevant challenge subject.', '2003-07-07 12:44:01.000000', NULL, 1),
(349005, 27190, 1202, '<td valign="top">No it''s Superman.   Nice job.  9</td>', 'No it''s Superman.   Nice job.  9', '2003-07-07 12:44:59.000000', NULL, 1),
