(349459, 26432, 7291, '<td valign="top">Judging by this picture...I''d be afraid to ride that thing.  Good job conveying speed.</td>', 'Judging by this picture...I''d be afraid to ride that thing.  Good job conveying speed.', '2003-07-07 19:06:30.000000', NULL, 1),
