(349468, 27112, 7291, '<td valign="top">Just a bit overdone on the choice of color scheme, but it does a good job of getting the point accross.</td>', 'Just a bit overdone on the choice of color scheme, but it does a good job of getting the point accross.', '2003-07-07 19:19:56.000000', NULL, 1),
(349469, 26906, 7291, '<td valign="top">Very cool.  It must take good timing to accomplish that effect.  Especially at that speed.</td>', 'Very cool.  It must take good timing to accomplish that effect.  Especially at that speed.', '2003-07-07 19:20:35.000000', NULL, 1),
(349470, 27101, 7291, '<td valign="top">I think this picture is incredible.  With the stationay subject being off-center and the choice of black &amp; white, I give this a 10.</td>', 'I think this picture is incredible.  With the stationay subject being off-center and the choice of black & white, I give this a 10.', '2003-07-07 19:21:41.000000', NULL, 1),
(349471, 27071, 7291, '<td valign="top">Funy.  I had the same idea but didn''t know where to find a snail.  Good job.</td>', 'Funy.  I had the same idea but didn''t know where to find a snail.  Good job.', '2003-07-07 19:22:31.000000', NULL, 1),
(349479, 26978, 7291, '<td valign="top">Oh man......that''s just gross.  LOL!</td>', 'Oh man......that''s just gross.  LOL!', '2003-07-07 19:32:45.000000', NULL, 1),
(349489, 27105, 1647, '<td valign="top">It''s an interesting composition - the peace offered by the seat with the motion offered by the fountain.  It''s probably not the best representation of speed, but still an interesting photo.</td>', 'It''s an interesting composition - the peace offered by the seat with the motion offered by the fountain.  It''s probably not the best representation of speed, but still an interesting photo.', '2003-07-07 19:41:38.000000', NULL, 1),
