INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(349494, 27146, 1647, '<td valign="top">It''s a lovely photo.  The blue is wonderful and the composition is great.</td>', 'It''s a lovely photo.  The blue is wonderful and the composition is great.', '2003-07-07 19:45:43.000000', NULL, 1),
(349495, 27049, 1647, '<td valign="top">Cute shot - looks like a hot supra with those fat back tires. :-)</td>', 'Cute shot - looks like a hot supra with those fat back tires. :-)', '2003-07-07 19:46:20.000000', NULL, 1),
(349497, 27052, 1647, '<td valign="top">Great shot - it conveys speed very well, is nicely composed and the driver is easily visible.  Well done.</td>', 'Great shot - it conveys speed very well, is nicely composed and the driver is easily visible.  Well done.', '2003-07-07 19:47:12.000000', NULL, 1),
(349499, 26906, 1647, '<td valign="top">I like the shot but the composition just doesn''t seem quite right.  The cars seem very small.  Technically the sharpness is very good - your panning is great.</td>', 'I like the shot but the composition just doesn''t seem quite right.  The cars seem very small.  Technically the sharpness is very good - your panning is great.', '2003-07-07 19:49:18.000000', NULL, 1),
(349500, 26997, 1647, '<td valign="top">I like this shot - it has quite an artistic quality about it, whilst also easily meeting the speed challenge.</td>', 'I like this shot - it has quite an artistic quality about it, whilst also easily meeting the speed challenge.', '2003-07-07 19:49:58.000000', NULL, 1),
(349501, 26998, 1647, '<td valign="top">Great shot - if the weather had been a little finer I think BMW could have used the shot for advertising almost.  It captures the speed of the car very well, is nicely composed and has a lovely background.</td>', 'Great shot - if the weather had been a little finer I think BMW could have used the shot for advertising almost.  It captures the speed of the car very well, is nicely composed and has a lovely background.', '2003-07-07 19:52:08.000000', NULL, 1),
(349502, 27068, 9462, '<td valign="top">Good idea but it doesn''t give me any feelings of speed. Could''ve gone without the filters.</td>', 'Good idea but it doesn''t give me any feelings of speed. Could''ve gone without the filters.', '2003-07-07 19:53:22.000000', NULL, 1),
(349503, 27068, 1647, '<td valign="top">I really like the way the key words stand out although I think a different title may have explained your purpose better.</td>', 'I really like the way the key words stand out although I think a different title may have explained your purpose better.', '2003-07-07 19:54:15.000000', NULL, 1),
(349505, 26852, 1647, '<td valign="top">Nice blurring of the background.  The network plug is particularly appropriate to your shot.  This could easily become a desktop wallpaper.  Also, good job lighting the clear plastic plug without too much glare.</td>', 'Nice blurring of the background.  The network plug is particularly appropriate to your shot.  This could easily become a desktop wallpaper.  Also, good job lighting the clear plastic plug without too much glare.', '2003-07-07 19:55:56.000000', NULL, 1),
(349507, 27190, 1647, '<td valign="top">It''s an interesting shot - I can''t work out how you did this since there don''t appear to be any wheels involved.</td>', 'It''s an interesting shot - I can''t work out how you did this since there don''t appear to be any wheels involved.', '2003-07-07 19:58:16.000000', NULL, 1),
(349508, 27199, 1647, '<td valign="top">I understand your title, but don''t think it conveys speed really well.  Having said that, it''s a wonderful shot and is composed brilliantly.  It would make a great piece of stock photography.</td>', 'I understand your title, but don''t think it conveys speed really well.  Having said that, it''s a wonderful shot and is composed brilliantly.  It would make a great piece of stock photography.', '2003-07-07 19:59:18.000000', NULL, 1),
(349536, 26699, 9810, '<td valign="top">I dont like it at all, I think the effect that you used is used to much in the contest and thus doesnt make the photo original.</td>', 'I dont like it at all, I think the effect that you used is used to much in the contest and thus doesnt make the photo original.', '2003-07-07 20:34:27.000000', NULL, 1),
(349538, 27158, 9810, '<td valign="top">I like how the water looks in this photo, although it doesnt have alot to do with speed, its still a cool picture.</td>', 'I like how the water looks in this photo, although it doesnt have alot to do with speed, its still a cool picture.', '2003-07-07 20:35:07.000000', NULL, 1),
(349539, 26733, 9810, '<td valign="top">Its a cool picture, I wonder what kinda bug it is. I like how you cant see the wings.</td>', 'Its a cool picture, I wonder what kinda bug it is. I like how you cant see the wings.', '2003-07-07 20:35:52.000000', NULL, 1),
(349543, 26932, 9810, '<td valign="top">Well, there fast. The fact that the boat in the back is blurred makes this photo all the better, the only thing I would have changed is to try and get more spray from the sea doo in the picture.</td>', 'Well, there fast. The fact that the boat in the back is blurred makes this photo all the better, the only thing I would have changed is to try and get more spray from the sea doo in the picture.', '2003-07-07 20:37:36.000000', NULL, 1),
(349546, 26837, 9810, '<td valign="top">My god I hope the driver didnt take the photo.</td>', 'My god I hope the driver didnt take the photo.', '2003-07-07 20:38:09.000000', NULL, 1),
(349548, 26991, 9810, '<td valign="top">I dont like the effect you used, it''s confusing and hurts my eyes.</td>', 'I dont like the effect you used, it''s confusing and hurts my eyes.', '2003-07-07 20:39:21.000000', NULL, 1),
(349551, 27197, 9810, '<td valign="top">I dont like it at all, I think the effect that you used is used to much in the contest and thus doesnt make the photo original.</td>', 'I dont like it at all, I think the effect that you used is used to much in the contest and thus doesnt make the photo original.', '2003-07-07 20:41:22.000000', NULL, 1),
(349556, 26802, 9810, '<td valign="top">I like the title.</td>', 'I like the title.', '2003-07-07 20:42:20.000000', NULL, 1),
(349580, 27037, 1202, '<td valign="top">You nailed it with this one.  Simply superb shot.   10</td>', 'You nailed it with this one.  Simply superb shot.   10', '2003-07-07 20:56:53.000000', NULL, 1),
(349597, 26964, 2158, '<td valign="top">I feel there is a bit too much black at the bottom, also I would have like to see the girl a bit off-centre.  Perhaps you could try cropping off some of the bottom and the right hand side (if the original file is large enough to allow this).  Overall I like this picture - I''m just not sure it''s right for this challenge.</td>', 'I feel there is a bit too much black at the bottom, also I would have like to see the girl a bit off-centre.  Perhaps you could try cropping off some of the bottom and the right hand side (if the original file is large enough to allow this).  Overall I like this picture - I''m just not sure it''s right for this challenge.', '2003-07-07 21:07:22.000000', NULL, 1),
(349602, 26634, 1202, '<td valign="top">What speed is the old dog doing anyway?   I can''t make the connection.  If it met the challenge I would say that the top of his head is really overexposed and washed out.   I don''t like the dark area on the right eithe r it would be better if things like this were avoided.   3</td>', 'What speed is the old dog doing anyway?   I can''t make the connection.  If it met the challenge I would say that the top of his head is really overexposed and washed out.   I don''t like the dark area on the right eithe r it would be better if things like this were avoided.   3', '2003-07-07 21:12:45.000000', NULL, 1),
(349606, 27165, 1202, '<td valign="top">What are the little white spots?   Very distracting.   4</td>', 'What are the little white spots?   Very distracting.   4', '2003-07-07 21:21:39.000000', NULL, 1),
(349635, 26390, 9093, '<td valign="top">I like the composition of the photo.  However the shutter speed is so fast, it looks like she''s hardly moving at all.  I would love to see this same photo with a slower shutter speed and a flash at the end to give a larger sense of motion.  Nice shot though!</td>', 'I like the composition of the photo.  However the shutter speed is so fast, it looks like she''s hardly moving at all.  I would love to see this same photo with a slower shutter speed and a flash at the end to give a larger sense of motion.  Nice shot though!', '2003-07-07 22:17:12.000000', NULL, 1),
(349639, 27071, 6325, '<td valign="top">Cool. Very sharp. Nice challenge shot.</td>', 'Cool. Very sharp. Nice challenge shot.', '2003-07-07 22:22:59.000000', NULL, 1),
(349640, 26763, 6325, '<td valign="top">The car is really hopping. I like to see some open space in the fron of the car so it has someplace to go.</td>', 'The car is really hopping. I like to see some open space in the fron of the car so it has someplace to go.', '2003-07-07 22:24:59.000000', NULL, 1),
